func resourceComputeDhcpOptionsConfigDelete(d *schema.ResourceData, meta interface{}) error {
	if d.Get("deletion_policy").(string) == "PREVENT" {
		return fmt.Errorf("cannot destroy ComputeDhcpOptionsConfig without setting deletion_policy=\"DELETE\" and running `terraform apply`")
	}
	if d.Get("deletion_policy").(string) == "ABANDON" {
		log.Printf("[DEBUG] deletion_policy set to \"ABANDON\", removing DhcpOptionsConfig %q from Terraform state without deletion", d.Id())
		return nil
	}
	config := meta.(*transport_tpg.Config)
	userAgent, err := tpgresource.GenerateUserAgentString(d, config.UserAgent)
	if err != nil {
		return err
	}

	billingProject := ""

	project, err := tpgresource.GetProject(d, config)
	if err != nil {
		return fmt.Errorf("Error fetching project for DhcpOptionsConfig: %s", err)
	}
	billingProject = project
	url, err := tpgresource.ReplaceVars(d, config, transport_tpg.BaseUrl(Product, config)+"projects/{{project}}/regions/{{region}}/dhcpOptionsConfigs/{{name}}")
	if err != nil {
		return err
	}

	var obj map[string]interface{}

	// err == nil indicates that the billing_project value was found
	if bp, err := tpgresource.GetBillingProject(d, config); err == nil {
		billingProject = bp
	}

	headers := make(http.Header)
	// Compute DhcpOptionsConfig Delete fails if any network associations remain.
	// Only clear associations automatically before deleting when deletion_policy is "FORCE".
	// Otherwise let DELETE run so Compute Engine deletes unassociated configs or fails with an association error.
	if deletionPolicy, _ := d.Get("deletion_policy").(string); deletionPolicy == "FORCE" {
		getRes, getErr := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
			Config:    config,
			Method:    "GET",
			Project:   billingProject,
			RawURL:    url,
			UserAgent: userAgent,
			Timeout:   d.Timeout(schema.TimeoutDelete),
			Headers:   headers,
		})
		if getErr != nil {
			return transport_tpg.HandleNotFoundError(getErr, d, fmt.Sprintf("DhcpOptionsConfig %q", d.Id()))
		}
		if assocs, ok := getRes["associations"].(map[string]interface{}); ok && len(assocs) > 0 {
			clearUrl, err := transport_tpg.AddQueryParams(url, map[string]string{"updateMask": "associations"})
			if err != nil {
				return err
			}

			log.Printf("[DEBUG] Clearing associations before deleting DhcpOptionsConfig %q", d.Id())
			patchRes, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "PATCH",
				Project:   billingProject,
				RawURL:    clearUrl,
				UserAgent: userAgent,
				Body:      map[string]interface{}{},
				Timeout:   d.Timeout(schema.TimeoutDelete),
				Headers:   headers,
			})
			if err != nil {
				return fmt.Errorf("Error clearing associations before deleting DhcpOptionsConfig %q: %s", d.Id(), err)
			}

			err = ComputeOperationWaitTime(
				config, patchRes, project, "Clearing DhcpOptionsConfig associations", userAgent,
				d.Timeout(schema.TimeoutDelete))
			if err != nil {
				return fmt.Errorf("Error waiting to clear DhcpOptionsConfig associations %q: %s", d.Id(), err)
			}
		}
	}

	log.Printf("[DEBUG] Deleting DhcpOptionsConfig %q", d.Id())
	res, err := transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
		Config:    config,
		Method:    "DELETE",
		Project:   billingProject,
		RawURL:    url,
		UserAgent: userAgent,
		Body:      obj,
		Timeout:   d.Timeout(schema.TimeoutDelete),
		Headers:   headers,
	})
	if err != nil {
		return transport_tpg.HandleNotFoundError(err, d, "DhcpOptionsConfig")
	}

	err = ComputeOperationWaitTime(
		config, res, project, "Deleting DhcpOptionsConfig", userAgent,
		d.Timeout(schema.TimeoutDelete))

	if err != nil {
		return err
	}

	log.Printf("[DEBUG] Finished deleting DhcpOptionsConfig %q: %#v", d.Id(), res)
	return nil
}

